#include <iostream>
#include <vector>
#include <string>
using namespace std;

// 计算单组测试数据的答案
int min_k_prefix_length(int n, int k, const string& s) {
    // 记录所有字符 '1' 的下标
    vector<int> pos;
    for (int i = 0; i < n; i++) {
        if (s[i] == '1') {
            pos.push_back(i);
        }
    }

    int m = (int)pos.size();

    // 如果总共不足 k 个 '1'，则无解
    if (m < k) {
        return -1;
    }

    // 构造扩展数组，把环形下标拉直
    vector<int> ext(2 * m);
    for (int i = 0; i < m; i++) {
        ext[i] = pos[i];
        ext[i + m] = pos[i] + n;
    }

    int ans = n + 1;

    // 枚举每个 '1' 作为起点，统计连续 k 个 '1' 的覆盖长度
    for (int i = 0; i < m; i++) {
        int length = ext[i + k - 1] - ext[i] + 1;
        if (length < ans) {
            ans = length;
        }
    }

    return ans;
}

